// Floor heights of the Underwater Plaza, measured from its model: the highest upward-facing
// surface in every 1 cm square of model space (192 x 192 cells over -0.96..0.96), in thousandths
// of a model unit. -32768 marks open water. Cells are stored row by row (z, then x).
const encoded='';
const cells=192,cell=.01,origin=-.96,empty=-32768;
const raw=Uint8Array.from(atob(encoded),character=>character.charCodeAt(0));
const heights=new Int16Array(raw.buffer);

// The plaza sits in the world with its model origin at (x,y,z) and this scale.
export const plazaFrame={x:-9,y:-.505,z:4.2,scale:15};

function cellAt(ix,iz){
  if(ix<0||iz<0||ix>=cells||iz>=cells)return empty;
  return heights[iz*cells+ix];
}

// Model-space floor height at a point, or undefined over open water.
function modelFloor(mx,mz){
  const fx=(mx-origin)/cell-.5,fz=(mz-origin)/cell-.5;
  const ix=Math.floor(fx),iz=Math.floor(fz),tx=fx-ix,tz=fz-iz;
  let total=0,weight=0;
  for(const [dx,dz,w] of [[0,0,(1-tx)*(1-tz)],[1,0,tx*(1-tz)],[0,1,(1-tx)*tz],[1,1,tx*tz]]){
    const h=cellAt(ix+dx,iz+dz);
    if(h===empty||w<=0)continue;
    total+=h*w;weight+=w;
  }
  return weight>.0001?total/weight/1000:undefined;
}

// World-space floor height. Over water it blends toward the nearest floor, so a swimmer drifting
// off an island eases back down instead of snapping.
const hubFloor=.047;
// True where there is a floor under the point (an island, bridge or stair), false over open water.
export function onPlazaFloor(x,z){
  const {x:ox,z:oz,scale}=plazaFrame;
  return modelFloor((x-ox)/scale,(z-oz)/scale)!==undefined;
}

const smooth=(value,low,high)=>{const t=Math.min(1,Math.max(0,(value-low)/(high-low)));return t*t*(3-2*t);};
export function floorAt(x,z){
  // Beyond the plaza (the Sanctuary crossing in the west, Moonlace Reef in the east) the ground is level.
  const reach=smooth(x,-24,-20)*(1-smooth(x,3,6));
  return reach>0?plazaFloor(x,z)*reach:0;
}

function plazaFloor(x,z){
  const {x:ox,y:oy,z:oz,scale}=plazaFrame;
  const mx=(x-ox)/scale,mz=(z-oz)/scale;
  const here=modelFloor(mx,mz);
  if(here!==undefined)return oy+here*scale;
  let nearest,best=Infinity;
  for(let ring=1;ring<=12;ring++){
    for(let a=0;a<16;a++){
      const angle=a/16*Math.PI*2;
      const h=modelFloor(mx+Math.cos(angle)*ring*cell*2,mz+Math.sin(angle)*ring*cell*2);
      if(h!==undefined&&ring<best){best=ring;nearest=h;}
    }
    if(nearest!==undefined)break;
  }
  return oy+(nearest??hubFloor)*scale;
}
